import 'dart:async';\nimport 'dart:typed_data';\nimport 'package:fftea/fftea.dart';\nimport 'package:record/record.dart';\nimport 'device_state_provider.dart';\n\nclass MusicSyncEngine {\n  final AudioRecorder _audioRecorder = AudioRecorder();\n  final DeviceStateProvider _provider;\n  final String _deviceId;\n  \n  StreamSubscription<Uint8List>? _micSubscription;\n  final FFT _fft = FFT(1024); // 1024 samples\n  \n  bool _isSyncing = false;\n  bool get isSyncing => _isSyncing;\n\n  MusicSyncEngine(this._provider, this._deviceId);\n\n  Future<void> startSync() async {\n    if (await _audioRecorder.hasPermission()) {\n      _isSyncing = true;\n\n      // Start listening to mic as a raw PCM stream\n      final stream = await _audioRecorder.startStream(const RecordConfig(\n        encoder: AudioEncoder.pcm16bits,\n        sampleRate: 44100,\n        numChannels: 1,\n      ));\n\n      _micSubscription = stream.listen((data) {\n        _processAudioChunk(data);\n      });\n    }\n  }\n\n  void stopSync() {\n    _isSyncing = false;\n    _micSubscription?.cancel();\n    _audioRecorder.stop();\n  }\n\n  void _processAudioChunk(Uint8List data) {\n    if (!_isSyncing) return;\n\n    // Convert 16-bit PCM to Float64 list for FFT\n    final buffer = data.buffer.asInt16List();\n    if (buffer.length < 1024) return;\n    \n    final floatInput = Float64List(1024);\n    for (int i = 0; i < 1024; i++) {\n      floatInput[i] = buffer[i] / 32768.0;\n    }\n\n    // Run FFT\n    final spectrum = _fft.realFft(floatInput);\n    \n    // Extremely simple bucket analysis for visualizer demo\n    double bass = 0.0;\n    for (int i = 1; i < 10; i++) {\n      bass += spectrum[i].distance;\n    }\n    \n    // Map bass energy (0.0 -> ~100.0) to Brightness and color shifts\n    int v = (bass * 2.5).clamp(0, 254).toInt();\n    // Slowly rotate hue\n    int h = (DateTime.now().millisecondsSinceEpoch / 20 % 254).toInt();\n    int s = 254; // Keep colors saturated\n\n    // Fire fast path straight to the backend Gateway avoiding HTTP overhead\n    _provider.sendMusicSyncFrame(_deviceId, h, s, v);\n  }\n}\n
